			t.Errorf("stop = %+v, want it still forcing", s)
		}
		if m.portsModel.footer.Text() != before || cmd != nil {
			t.Errorf("footer = %q (was %q), command = %v: a late tick had an effect", m.portsModel.footer.Text(), before, cmd != nil)
		}''')
